script:
test("exactly 10000.00 belongs to the lower band and earns nothing", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.00 }), {
    rebate: 0.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 0.00, amount: 0 },
      { rate: 0.03, portion: 0.00, amount: 0 }
    ]
  });
});

test("one step below 10000.00 stays entirely in the zero percent band", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 9999.99 }), {
    rebate: 0.00,
    bands: [
      { rate: 0, portion: 9999.99, amount: 0 },
      { rate: 0.02, portion: 0.00, amount: 0 },
      { rate: 0.03, portion: 0.00, amount: 0 }
    ]
  });
});

test("one step above 10000.00 rounds 2 percent of 0.01 to the nearest cent", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.01 }), {
    rebate: 0.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 0.01, amount: 0.0002 },
      { rate: 0.03, portion: 0.00, amount: 0 }
    ]
  });
});

test("exactly 50000.00 earns only the 2 percent band", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 50000.00 }), {
    rebate: 800.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 40000.00, amount: 800.00 },
      { rate: 0.03, portion: 0.00, amount: 0 }
    ]
  });
});

test("one step below 50000.00 rounds 799.9998 to the nearest cent", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 49999.99 }), {
    rebate: 800.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 39999.99, amount: 799.9998 },
      { rate: 0.03, portion: 0.00, amount: 0 }
    ]
  });
});

test("one step above 50000.00 puts the excess in the 3 percent band and rounds to the nearest cent", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 50000.01 }), {
    rebate: 800.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 40000.00, amount: 800.00 },
      { rate: 0.03, portion: 0.01, amount: 0.0003 }
    ]
  });
});

test("purchases of 60000.00 earn 2 percent of 40000.00 plus 3 percent of 10000.00", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 60000.00 }), {
    rebate: 1100.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 40000.00, amount: 800.00 },
      { rate: 0.03, portion: 10000.00, amount: 300.00 }
    ]
  });
});

test("purchases of 10000.50 earn 2 percent of 0.50", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.50 }), {
    rebate: 0.01,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 0.50, amount: 0.01 },
      { rate: 0.03, portion: 0.00, amount: 0 }
    ]
  });
});

test("purchases of 10000.24 round 0.0048 down to the nearest cent", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.24 }), {
    rebate: 0.00,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 0.24, amount: 0.0048 },
      { rate: 0.03, portion: 0.00, amount: 0 }
    ]
  });
});

test("purchases of 10000.26 round 0.0052 up to the nearest cent", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 10000.26 }), {
    rebate: 0.01,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 0.26, amount: 0.0052 },
      { rate: 0.03, portion: 0.00, amount: 0 }
    ]
  });
});

test("purchases of 50000.49 round 800.0147 to the nearest cent", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 50000.49 }), {
    rebate: 800.01,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 40000.00, amount: 800.00 },
      { rate: 0.03, portion: 0.49, amount: 0.0147 }
    ]
  });
});

test("purchases of 50000.51 round 800.0153 to the nearest cent", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 50000.51 }), {
    rebate: 800.02,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 40000.00, amount: 800.00 },
      { rate: 0.03, portion: 0.51, amount: 0.0153 }
    ]
  });
});

test("an uneven amount inside the 2 percent band rounds once to the nearest cent", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 22345.26 }), {
    rebate: 246.91,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 12345.26, amount: 246.9052 },
      { rate: 0.03, portion: 0.00, amount: 0 }
    ]
  });
});

test("uneven portions in all three bands round the sum once to the nearest cent", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 67890.17 }), {
    rebate: 1336.71,
    bands: [
      { rate: 0, portion: 10000.00, amount: 0 },
      { rate: 0.02, portion: 40000.00, amount: 800.00 },
      { rate: 0.03, portion: 17890.17, amount: 536.7051 }
    ]
  });
});

test("the smallest allowed 2 decimal amount stays in the zero percent band", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 0.01 }), {
    rebate: 0.00,
    bands: [
      { rate: 0, portion: 0.01, amount: 0 },
      { rate: 0.02, portion: 0.00, amount: 0 },
      { rate: 0.03, portion: 0.00, amount: 0 }
    ]
  });
});

test("the value one written as 1 and as 1.00 both earn nothing", function () {
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 1 }), {
    rebate: 0.00,
    bands: [
      { rate: 0, portion: 1.00, amount: 0 },
      { rate: 0.02, portion: 0.00, amount: 0 },
      { rate: 0.03, portion: 0.00, amount: 0 }
    ]
  });
  assert.deepEqual(code.calculateQuarterlyRebate({ quarterlyPurchases: 1.00 }), {
    rebate: 0.00,
    bands: [
      { rate: 0, portion: 1.00, amount: 0 },
      { rate: 0.02, portion: 0.00, amount: 0 },
      { rate: 0.03, portion: 0.00, amount: 0 }
    ]
  });
});
